    _a = sys.argv[1:]
    if _a and _a[0] == "--tool":
        print(json.dumps(RappAgentBridgeAgent().to_tool(), indent=2))
    else:
        _raw = _a[0] if _a else (sys.stdin.read().strip() or "{}")
        print(RappAgentBridgeAgent().perform(**json.loads(_raw)))

